final class CommuteService {
 public static function demoEnabled():bool{return app()->environment('testing')&&filter_var(getenv('MOBILITY_PILOT_UI_ENABLED'),FILTER_VALIDATE_BOOLEAN);}
 public static function demoActor(int$id):bool{return self::demoEnabled()&&DB::table('mobility_commute_demo_actors')->where('user_id',$id)->exists();}
 public function requireDemo(User$u):void{if(!self::demoActor($u->id)||!CohortPolicy::approved($u->id))throw new SegmentException('DEMO_SESSION_REQUIRED',403);}
 private function actor(string$key,string$name):User {
  $row=DB::table('mobility_commute_demo_actors')->where('fixture_key',$key)->first();if($row)return User::findOrFail($row->user_id);
  return DB::transaction(function()use($key,$name){$email='commute-'.$key.'@example.invalid';$u=User::where('email',$email)->lockForUpdate()->first();if(!$u)$u=User::factory()->create(['email'=>$email,'name'=>$name,'active'=>true,'banned'=>false]);
   DB::table('mobility_commute_demo_actors')->insertOrIgnore(['user_id'=>$u->id,'fixture_key'=>$key,'created_at'=>now(),'updated_at'=>now()]);
   DB::table('mobility_memberships')->insertOrIgnore(['user_id'=>$u->id,'college_code'=>CohortPolicy::college(),'affiliation'=>'student','status'=>'approved','version'=>1,'created_at'=>now(),'updated_at'=>now()]);return$u;});
 }
 public function demoSession(string$role,?string$scenario=null):array {
  if(!self::demoEnabled())abort(404);$u=$this->actor($scenario==='campus-route'?($role==='driver'?'campus-driver-car':'campus-rider'):($role==='driver'?'driver-car':'rider'),$scenario==='campus-route'?($role==='driver'?'Yeshwanthpur Driver':'Laggere Rider'):'Demo '.ucfirst($role));
  return ['token'=>auth('api')->fromUser($u),'user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email],'profile'=>$this->profile($u),'driver_approved'=>$this->driverApproved($u),'demo'=>true,'scenario'=>$scenario];
 }
 public function profile(User$u):?array{$row=DB::table('mobility_commute_profiles')->where('user_id',$u->id)->first();if(!$row)return null;$p=json_decode($row->preferences,true)?:[];if(isset($row->same_gender_only))$p['same_gender_only']=(bool)$row->same_gender_only;if(isset($row->gender_identity))$p['gender_identity']=$row->gender_identity;return$p;}
 public function driverApproved(User$u):bool {
  if(!CohortPolicy::activeUser($u)||!CohortPolicy::approved($u->id))return false;
  return (self::demoActor($u->id)&&DB::table('mobility_commute_demo_actors')->where('user_id',$u->id)->whereIn('fixture_key',['driver-car','campus-driver-car'])->exists())||CohortPolicy::hostApproved($u->id);
 }
 public function me(User$u):array{return['user'=>['id'=>$u->id,'name'=>$u->name,'email'=>$u->email],'profile'=>$this->profile($u),'demo'=>self::demoActor($u->id),'operator'=>(bool)$u->is_admin,'driver_approved'=>$this->driverApproved($u)];}
 public function saveProfile(User$u,array$v):array{
  return DB::transaction(function()use($u,$v){if(isset($v['name'])){$u->name=$v['name'];$u->save();}unset($v['name']);$v['onboarding_complete']=true;$existing=DB::table('mobility_commute_profiles')->where('user_id',$u->id)->lockForUpdate()->first(['gender_identity','same_gender_only']);$gender=array_key_exists('gender_identity',$v)?$v['gender_identity']:($existing->gender_identity??null);$same=(bool)(array_key_exists('same_gender_only',$v)?$v['same_gender_only']:($existing->same_gender_only??false));if($same&&(!$gender||in_array($gender,['prefer_not_to_say','self_described'],true)))throw new SegmentException($gender==='self_described'?'SAME_GENDER_IDENTITY_UNMATCHABLE':'SAME_GENDER_IDENTITY_REQUIRED',422);unset($v['gender_identity'],$v['same_gender_only']);DB::table('mobility_commute_profiles')->updateOrInsert(['user_id'=>$u->id],['preferences'=>json_encode($v,JSON_THROW_ON_ERROR),'gender_identity'=>$gender,'same_gender_only'=>$same,'created_at'=>now(),'updated_at'=>now()]);return$this->me($u);});
 }
 public function rides(User$rider,string$direction,string$date,string$vehicle,string$pickupChoice='both'):array {
  return app(CommuteMatchingService::class)->rides($rider,$direction,$date,$vehicle,$pickupChoice);
 }
 public function joinWaitlist(User$rider,int$tripId,string$quote):array {
  $this->requireDemo($rider);
  return DB::transaction(function()use($rider,$tripId,$quote){
   $trip=Trip::whereKey($tripId)->lockForUpdate()->firstOrFail();
   $meta=DB::table('mobility_commute_demo_trips')->where('trip_id',$tripId)->where('is_publication',true)->first();
   if(!$meta)throw new SegmentException('DEMO_TRIP_REQUIRED',403);
   $match=app(CommuteMatchingService::class)->waitlistQuote($rider,$trip,$quote);
   if(Passenger::where('trip_id',$tripId)->where('user_id',$rider->id)->whereIn('request_state',[0,1])->exists())throw new SegmentException('BOOKING_ALREADY_EXISTS',409);
   if(DB::table('mobility_commute_waitlist')->where('trip_id',$tripId)->where('rider_id',$rider->id)->where('status','pending')->exists())return ['data'=>$this->waitlistDto(DB::table('mobility_commute_waitlist')->where('trip_id',$tripId)->where('rider_id',$rider->id)->where('status','pending')->first())];
   $used=Passenger::where('trip_id',$tripId)->where('request_state',1)->count();if($used < (int)$trip->total_seats)throw new SegmentException('WAITLIST_ONLY_WHEN_FULL',409);
   $id=DB::table('mobility_commute_waitlist')->insertGetId(['trip_id'=>$tripId,'rider_id'=>$rider->id,'match_key'=>$match->match_key,'status'=>'pending','created_at'=>now(),'updated_at'=>now()]);
   return ['data'=>$this->waitlistDto(DB::table('mobility_commute_waitlist')->where('id',$id)->first())];
  });
 }
 public function waitlist(User$u):array{$this->requireDemo($u);$rows=DB::table('mobility_commute_waitlist')->where('rider_id',$u->id)->whereIn('status',['pending','requested'])->orderBy('id')->get();$data=[];foreach($rows as$row){$trip=Trip::find($row->trip_id);if(!$trip)continue;$available=(int)$trip->total_seats-Passenger::where('trip_id',$trip->id)->where('request_state',1)->count();$ahead=DB::table('mobility_commute_waitlist')->where('trip_id',$trip->id)->whereIn('status',['pending','requested'])->where('id','<',$row->id)->exists();$data[]=$this->waitlistDto($row,$row->status==='pending'&&$available>0&&!$ahead,null);}return['data'=>$data,'demo_only'=>true,'actionable_is_snapshot'=>true];}
 public function refreshWaitlist(User$u,int$id):array{$this->requireDemo($u);$peek=DB::table('mobility_commute_waitlist')->where('id',$id)->where('rider_id',$u->id)->first();if(!$peek)throw new SegmentException('WAITLIST_FORBIDDEN',403);$this->expireInvalidWaitlistHeads((int)$peek->trip_id);return DB::transaction(function()use($u,$id){$peek=DB::table('mobility_commute_waitlist')->where('id',$id)->where('rider_id',$u->id)->first();if(!$peek)throw new SegmentException('WAITLIST_FORBIDDEN',403);if($peek->status==='expired')return['data'=>$this->waitlistDto($peek,false,null,'WAITLIST_HEAD_EXPIRED'),'demo_only'=>true];$trip=Trip::whereKey($peek->trip_id)->lockForUpdate()->firstOrFail();$row=DB::table('mobility_commute_waitlist')->where('id',$id)->where('rider_id',$u->id)->where('status','pending')->lockForUpdate()->first();if(!$row)throw new SegmentException('WAITLIST_FORBIDDEN',403);$match=app(CommuteMatchingService::class)->refreshWaitlistQuote($u,$trip,$row->match_key);$available=(int)$trip->total_seats-Passenger::where('trip_id',$trip->id)->where('request_state',1)->count();$ahead=DB::table('mobility_commute_waitlist')->where('trip_id',$trip->id)->whereIn('status',['pending','requested'])->where('id','<',$id)->exists();if($available<1||$ahead)throw new SegmentException('WAITLIST_NOT_ACTIONABLE',409);DB::table('mobility_commute_waitlist')->where('id',$id)->update(['match_key'=>$match->match_key,'updated_at'=>now()]);return['data'=>$this->waitlistTermsDto($row,$match),'demo_only'=>true];});}
 public function requestWaitlistSeat(User$u,int$id,string$quote,bool$consent):array{$this->requireDemo($u);if(!$consent)throw new SegmentException('WAITLIST_CONSENT_REQUIRED',422);return DB::transaction(function()use($u,$id,$quote){$peek=DB::table('mobility_commute_waitlist')->where('id',$id)->where('rider_id',$u->id)->first();if(!$peek)throw new SegmentException('WAITLIST_FORBIDDEN',403);$trip=Trip::whereKey($peek->trip_id)->lockForUpdate()->firstOrFail();$row=DB::table('mobility_commute_waitlist')->where('id',$id)->where('rider_id',$u->id)->where('status','pending')->lockForUpdate()->first();if(!$row)throw new SegmentException('WAITLIST_FORBIDDEN',403);$this->expireInvalidWaitlistHeads($trip->id);$ahead=DB::table('mobility_commute_waitlist')->where('trip_id',$trip->id)->whereIn('status',['pending','requested'])->where('id','<',$row->id)->exists();if($ahead)throw new SegmentException('WAITLIST_NOT_YOUR_TURN',409);if(!hash_equals($row->match_key,$quote))throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);$match=app(CommuteMatchingService::class)->waitlistQuote($u,$trip,$quote);$used=Passenger::where('trip_id',$trip->id)->where('request_state',1)->count();if($used >= (int)$trip->total_seats)throw new SegmentException('NOT_SEAT_AVAILABLE',422);$result=app(CommuteMatchingService::class)->request($u,$trip,$match->match_key);DB::table('mobility_commute_waitlist')->where('id',$id)->update(['status'=>'requested','consent_at'=>now(),'consent_quote_hash'=>hash('sha256',$quote),'updated_at'=>now()]);return$result;});}
 private function expireInvalidWaitlistHeads(int$tripId):void{$rows=DB::table('mobility_commute_waitlist')->where('trip_id',$tripId)->whereIn('status',['pending','requested'])->orderBy('id')->get();$t=DB::table('trips')->join('mobility_trip_lifecycles as l','l.trip_id','=','trips.id')->where('trips.id',$tripId)->first();foreach($rows as$row){if(Passenger::where('trip_id',$tripId)->where('user_id',$row->rider_id)->whereIn('request_state',[0,1])->exists())continue;$invalid=!$t||$t->state!=='planned'||CarbonImmutable::parse($t->trip_date,'Asia/Kolkata')->lte(now('Asia/Kolkata'));$r=User::find($row->rider_id);$p=$r?$this->profile($r):null;$invalid=$invalid||!$r||!CohortPolicy::activeUser($r)||!CohortPolicy::approved($r->id)||!$p; if(!$invalid){$m=DB::table('mobility_commute_matches')->where('match_key',$row->match_key)->first();$hash=isset($p['home'],$p['campus'],$p['outbound_time'],$p['return_time'])?hash('sha256',json_encode([$p['home'],$p['campus'],$p['outbound_time'],$p['return_time'],$p['max_walk_meters']??999])):'';$invalid=!$m||!hash_equals((string)$m->profile_hash,$hash);}if($invalid)DB::table('mobility_commute_waitlist')->where('id',$row->id)->update(['status'=>'expired','updated_at'=>now()]);}}
 public function cancelWaitlist(User$u,int$id):array{$this->requireDemo($u);return DB::transaction(function()use($u,$id){$row=DB::table('mobility_commute_waitlist')->where('id',$id)->lockForUpdate()->first();if(!$row||(int)$row->rider_id!==(int)$u->id)throw new SegmentException('WAITLIST_FORBIDDEN',403);if($row->status==='pending')DB::table('mobility_commute_waitlist')->where('id',$id)->update(['status'=>'cancelled','updated_at'=>now()]);return ['data'=>$this->waitlistDto(DB::table('mobility_commute_waitlist')->where('id',$id)->first())];});}
 private function waitlistDto(object$row,bool$actionable=false,?string$quote=null,?string$error=null):array{return ['id'=>(int)$row->id,'trip_id'=>(int)$row->trip_id,'rider_id'=>(int)$row->rider_id,'status'=>$row->status,'created_at'=>$row->created_at,'actionable'=>$actionable,'quote_token'=>$quote,'error'=>$error,'demo_only'=>true];}
 private function waitlistTermsDto(object$row,object$m):array{$j=json_decode($m->journey,true,512,JSON_THROW_ON_ERROR);return array_merge($this->waitlistDto($row,true,$m->match_key),['terms'=>['fare_minor'=>(int)$m->fare_minor,'base_fare_minor'=>(int)$m->base_fare_minor,'surcharge_minor'=>(int)$m->surcharge_minor,'pickup_at'=>CarbonImmutable::parse($m->pickup_at,'Asia/Kolkata')->toISOString(),'pickup_label'=>$j['rider_origin']['label']??'Pickup','dropoff_label'=>$j['rider_destination']['label']??'Destination','access_meters'=>(int)($j['access']['total_meters']??0),'egress_meters'=>(int)($j['egress']['total_meters']??0),'journey'=>$j]]);}
 private function quoteToken(object$m,User$u):string{return hash_hmac('sha256',$m->trip_id.':'.$u->id.':'.$m->fare_minor.':'.$m->fixture_key,(string)config('app.key'));}
 public function request(User$u,int$tripId,string$quote):array {
  $this->requireDemo($u);return DB::transaction(function()use($u,$tripId,$quote){$trip=Trip::whereKey($tripId)->lock('for update nowait')->firstOrFail();$meta=DB::table('mobility_commute_demo_trips')->where('trip_id',$tripId)->first();
   if($meta&&$meta->is_publication)return app(CommuteMatchingService::class)->request($u,$trip,$quote);
   if(!$meta||(int)$meta->audience_id!==$u->id||!hash_equals($this->quoteToken($meta,$u),$quote))throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);
   $profile=$this->profile($u);$matches=false;
   if($profile){$date=CarbonImmutable::parse($trip->trip_date,'Asia/Kolkata')->format('Y-m-d');foreach(['outbound','return']as$direction){$from=$profile[$direction==='outbound'?'home':'campus'];$to=$profile[$direction==='outbound'?'campus':'home'];$time=$profile[$direction==='outbound'?'outbound_time':'return_time'];$current=hash('sha256',json_encode([$u->id,$meta->vehicle_type,$date,$direction,$time,$from,$to]));if(hash_equals($meta->fixture_key,$current))$matches=true;}}
   if(!$matches)throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);
   if($trip->user_id==$u->id)throw new SegmentException('RIDER_CANNOT_BE_DRIVER',403);$this->planned($trip);
   $old=Passenger::where('trip_id',$tripId)->where('user_id',$u->id)->whereIn('request_state',[0,1])->first();
   if(!$old){$old=Passenger::create(['trip_id'=>$tripId,'user_id'=>$u->id,'request_state'=>0,'passenger_type'=>Passenger::TYPE_PASAJERO]);app(CommuteNotificationService::class)->bookingRequested($old,$trip);}
   return['data'=>$this->bookingDto($old,$u)];});
 }
 private function planned(Trip$t):void{if(DB::table('mobility_trip_lifecycles')->where('trip_id',$t->id)->value('state')!=='planned'||CarbonImmutable::parse($t->trip_date,'Asia/Kolkata')->lte(now('Asia/Kolkata')))throw new SegmentException('COMMUTE_TRIP_CLOSED',409);}
 public function bookings(User$u):array{
  $this->requireDemo($u);$rows=Passenger::whereExists(fn($q)=>$q->selectRaw('1')->from('mobility_commute_demo_trips')->whereColumn('mobility_commute_demo_trips.trip_id','trip_passengers.trip_id'))->where(function($q)use($u){$q->where('user_id',$u->id)->orWhereExists(fn($t)=>$t->selectRaw('1')->from('trips')->whereColumn('trips.id','trip_passengers.trip_id')->where('trips.user_id',$u->id));})->orderByDesc('id')->limit(50)->get();return['data'=>$rows->map(fn($b)=>$this->bookingDto($b,$u))->all()];
 }
 public function bookingDto(Passenger$b,User$u):array{
  $trip=Trip::findOrFail($b->trip_id);if((int)$b->user_id!==$u->id&&(int)$trip->user_id!==$u->id)throw new SegmentException('TRIP_FORBIDDEN',403);
  $meta=DB::table('mobility_commute_demo_trips')->where('trip_id',$trip->id)->first();$hold=DB::table('mobility_commute_demo_holds')->where('booking_id',$b->id)->first();
  $terms=$meta->is_publication?app(CommuteMatchingService::class)->terms($b):$meta;
  if(!$terms)throw new SegmentException('COMMUTE_QUOTE_CHANGED',409);
  $journey=json_decode($terms->journey,true);
  $departure=$meta->is_publication?$terms->pickup_at:$trip->trip_date;
  $receipt=DB::table('mobility_commute_demo_receipts')->where('booking_id',$b->id)->first();
  return array_replace(['route_map'=>CommuteMatchingService::mapData($journey),'driver_route_origin_label'=>$journey['driver_origin']['label']??null,'driver_route_destination_label'=>$journey['driver_destination']['label']??null,'ride_meters'=>$journey['riding']['distance_meters']??0,'ride_seconds'=>$journey['riding']['duration_seconds']??0,'detour_meters'=>$journey['detour']['added_distance_meters']??0,'detour_seconds'=>$journey['detour']['added_duration_seconds']??0,'access_meters'=>$journey['access']['total_meters']??0,'egress_meters'=>$journey['egress']['total_meters']??0,'choice'=>$journey['choice']??'DIRECT_RIDER_PICKUP','pickup_label'=>$journey['rider_origin']['label']??'Scheduled pickup','dropoff_label'=>$journey['rider_destination']['label']??'Scheduled destination','vehicle_type'=>$meta->vehicle_type,'trip_id'=>$trip->id,'booking_id'=>$b->id,'rider_id'=>$b->user_id,'driver_id'=>$trip->user_id,'rider_name'=>User::whereKey($b->user_id)->value('name'),'driver_name'=>User::whereKey($trip->user_id)->value('name'),'owner'=>(int)$trip->user_id===$u->id,'request_state'=>(int)$b->request_state,'participant_state'=>DB::table('mobility_trip_participants')->where('trip_id',$trip->id)->where('user_id',$b->user_id)->value('state')??'accepted','state'=>DB::table('mobility_trip_lifecycles')->where('trip_id',$trip->id)->value('state'),'fare_minor'=>(int)$terms->fare_minor,'wallet_state'=>$hold->state??'unpaid','rider_arrived_at'=>$hold->arrived_at??null,'release_at'=>$hold->release_at??null,'receipt'=>$receipt?['receipt_number'=>$receipt->receipt_number,'amount_minor'=>(int)$receipt->amount_minor,'currency'=>$receipt->currency,'confirmed_at'=>$receipt->confirmed_at,'demo_only'=>true,'non_redeemable'=>true]:null,'can_drive'=>(int)$trip->user_id===$u->id,'departure_at'=>CarbonImmutable::parse($departure,'Asia/Kolkata')->toISOString(),'demo_fixture'=>true],CommuteMatchingService::presentation($journey,CarbonImmutable::parse($departure,'Asia/Kolkata')->toISOString()));
 }
 public function action(User$u,int$id,string$action):array{
  $this->requireDemo($u);return DB::transaction(function()use($u,$id,$action){$pre=Passenger::findOrFail($id);$trip=Trip::whereKey($pre->trip_id)->lock('for update nowait')->firstOrFail();$b=Passenger::whereKey($id)->lockForUpdate()->firstOrFail();$this->bookingDto($b,$u);$this->planned($trip);$owner=(int)$trip->user_id===$u->id;
   if($action!=='cancel'&&!$owner)throw new SegmentException('TRIP_OWNER_REQUIRED',403);
   $target=['accept'=>1,'reject'=>2,'cancel'=>3][$action];if((int)$b->request_state===$target)return['data'=>$this->bookingDto($b,$u)];
   if(($target!==3&&(int)$b->request_state!==0)||($target===3&&!in_array((int)$b->request_state,[0,1])))throw new SegmentException('BOOKING_STATE_CHANGED',409);
   if($target===1){$published=DB::table('mobility_commute_demo_trips')->where('trip_id',$trip->id)->value('is_publication');if($published)app(CommuteMatchingService::class)->accept($trip,$b);User::whereKey($u->id)->lock('for update nowait')->first();if(Passenger::where('trip_id',$trip->id)->where('request_state',1)->count()>=$trip->total_seats)throw new SegmentException('NOT_SEAT_AVAILABLE',422);
    // Demo driver still cannot accept simultaneous obligations on another trip.
    $conflict=Passenger::where('request_state',1)->where('trip_id','<>',$trip->id)->whereExists(function($q)use($trip,$u){$q->selectRaw('1')->from('trips as occupied')->join('mobility_trip_lifecycles as l','l.trip_id','=','occupied.id')->whereColumn('occupied.id','trip_passengers.trip_id')->where('occupied.user_id',$u->id)->whereIn('l.state',['planned','in_progress'])->whereBetween('occupied.trip_date',[CarbonImmutable::parse($trip->trip_date)->subHour(),CarbonImmutable::parse($trip->trip_date)->addHour()]);})->lockForUpdate()->first();if($conflict)throw new SegmentException('DRIVER_ROUTE_OVERLAP',409);
   }
   if($target===3)$this->refund($b);$b->request_state=$target;$b->save();$term=DB::table('mobility_commute_booking_terms')->where('booking_id',$b->id)->first();$queue=DB::table('mobility_commute_waitlist')->where('trip_id',$trip->id)->where('rider_id',$b->user_id)->where('match_key',$term->match_key??'')->where('status','requested');if($target===1){$queued=$queue->first();if($queued&&!hash_equals((string)$queued->consent_quote_hash,hash('sha256',(string)$term->match_key)))throw new SegmentException('WAITLIST_CONSENT_MISMATCH',409);$queue->update(['status'=>'fulfilled','updated_at'=>now()]);}if($target===2)$queue->update(['status'=>'pending','updated_at'=>now()]);if($target===3)$queue->update(['status'=>'cancelled','updated_at'=>now()]);app(CommuteNotificationService::class)->bookingAction($b->fresh(),$trip,$action==='accept'?'booking_accepted':($action==='reject'?'booking_rejected':'booking_cancelled'),$u);return['data'=>$this->bookingDto($b->fresh(),$u)];});
 }
